package com.acme.auth

import java.time.Instant
import java.util.concurrent.ConcurrentHashMap
import scala.collection.mutable

// Tenant-aware logging abstraction
trait AuditLogger {
  def log(level: String, tenantId: String, message: String): Unit
}

class StructuredAuditLogger extends AuditLogger {
  private val buffer = new mutable.ArrayBuffer[String]()

  override def log(level: String, tenantId: String, message: String): Unit = {
    val timestamp = Instant.now().toString
    val entry = s"[$timestamp] [$level] [tenant=$tenantId] $message"
    buffer.synchronized {
      buffer.append(entry)
    }
    // In production, this writes to a file/SIEM
    println(entry)
  }

  def getEntries: Seq[String] = buffer.synchronized { buffer.toSeq }
}

// Tenant context propagation
case class TenantContext(tenantId: String, realm: String)

object TenantContext {
  private val contextStore = new ConcurrentHashMap[Long, TenantContext]()

  def set(ctx: TenantContext): Unit =
    contextStore.put(Thread.currentThread().getId, ctx)

  def get: Option[TenantContext] =
    Option(contextStore.get(Thread.currentThread().getId))

  def clear(): Unit =
    contextStore.remove(Thread.currentThread().getId)
}

// Credential normalization pipeline
object CredentialNormalizer {
  // Normalize unicode in usernames for consistent lookup
  def normalizeUsername(raw: String): String = {
    java.text.Normalizer.normalize(raw, java.text.Normalizer.Form.NFKC)
  }

  // Sanitize for safe storage/comparison - strips control chars
  def sanitizeForStorage(input: String): String = {
    input.filter(c => !Character.isISOControl(c) || c == '\t')
  }

  // Prepare display name for audit trail
  def prepareForAudit(username: String, tenantCtx: TenantContext): String = {
    // Apply tenant-specific display rules
    val normalized = normalizeUsername(username)
    val displayReady = if (tenantCtx.realm == "internal") {
      // Internal realm: preserve original formatting for debugging
      normalized
    } else {
      // External realm: full sanitization
      sanitizeForStorage(normalized)
    }
    displayReady
  }
}

// Authentication result
sealed trait AuthResult
case class AuthSuccess(username: String, roles: Set[String]) extends AuthResult
case class AuthFailure(username: String, reason: String) extends AuthResult

// Main authentication service
class MultiTenantAuthService(logger: AuditLogger) {

  private val credentialStore = new ConcurrentHashMap[String, String]()

  def registerUser(tenantId: String, username: String, passwordHash: String): Unit = {
    val key = s"$tenantId:$username"
    credentialStore.put(key, passwordHash)
  }

  def authenticate(username: String, password: String): AuthResult = {
    val tenantCtx = TenantContext.get.getOrElse(
      TenantContext("default", "external")
    )

    val normalizedUser = CredentialNormalizer.normalizeUsername(username)
    val key = s"${tenantCtx.tenantId}:$normalizedUser"

    val storedHash = Option(credentialStore.get(key))

    val result = storedHash match {
      case Some(hash) if verifyPassword(password, hash) =>
        AuthSuccess(normalizedUser, Set("user"))
      case Some(_) =>
        AuthFailure(normalizedUser, "invalid_credentials")
      case None =>
        AuthFailure(normalizedUser, "user_not_found")
    }

    // Audit the authentication attempt
    logAuthAttempt(result, tenantCtx)
    result
  }

  private def logAuthAttempt(result: AuthResult, ctx: TenantContext): Unit = {
    result match {
      case AuthSuccess(user, _) =>
        val auditName = CredentialNormalizer.prepareForAudit(user, ctx)
        logger.log("INFO", ctx.tenantId, s"Authentication successful for user=$auditName")
      case AuthFailure(user, reason) =>
        val auditName = CredentialNormalizer.prepareForAudit(user, ctx)
        logger.log("WARN", ctx.tenantId, s"Authentication failed for user=$auditName reason=$reason")
    }
  }

  private def verifyPassword(provided: String, storedHash: String): Boolean = {
    // Simplified - in production use bcrypt/argon2
    import java.security.MessageDigest
    val digest = MessageDigest.getInstance("SHA-256")
    val hash = digest.digest(provided.getBytes("UTF-8")).map("%02x".format(_)).mkString
    MessageDigest.isEqual(hash.getBytes, storedHash.getBytes)
  }
}

// Demonstrates the cross-tenant log injection attack vector
object AuthDemo extends App {
  val logger = new StructuredAuditLogger()
  val service = new MultiTenantAuthService(logger)

  // Setup: register a user in tenant "acme"
  service.registerUser("acme", "alice", "dummy_hash")

  // Attacker sets internal realm context (e.g., via header manipulation)
  TenantContext.set(TenantContext("acme", "internal"))

  // Attacker username contains newline + fake log entry
  val maliciousUser = "bob\n[2024-01-01T00:00:00Z] [INFO] [tenant=acme] Authentication successful for user=admin"
  service.authenticate(maliciousUser, "anything")

  TenantContext.clear()
}
